import{_ as a,o as i,c as o,a5 as n}from"./chunks/framework.BwlBv862.js";const m=JSON.parse('{"title":"Iniciar sesión en tu cuenta de Cloud","description":"","frontmatter":{"title":"Iniciar sesión en tu cuenta de Cloud","docId":"user.cloud.account","translationKey":"user.cloud.account","locale":"es","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"02b7718e7fc7b2a53b68ee1c6e19e622608a6fdfc7eac553879c474ca69ea74b","translationRevision":"c621eebc98665ab57a08cd00eae611a2fee2925a81854f247fbfcf5042ec4b6a","order":10},"headers":[],"relativePath":"es/user/cloud/account.md","filePath":"es/user/cloud/account.md","lastUpdated":1794611623000}'),s={name:"es/user/cloud/account.md"};function r(t,e,c,l,d,u){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="sign-in-to-your-cloud-account" tabindex="-1">Iniciar sesión en tu cuenta de Cloud <a class="header-anchor" href="#sign-in-to-your-cloud-account" aria-label="Permalink to &quot;Iniciar sesión en tu cuenta de Cloud {#sign-in-to-your-cloud-account}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Conecta la aplicación de escritorio a su servicio Cloud configurado para operaciones de catálogo y colaboración vinculadas a una cuenta. Necesitas Internet, un navegador del sistema y un almacén de credenciales del sistema operativo funcional. La edición local sigue siendo útil sin Cloud; su sesión no autentica la conexión LIVE de TikTok.</p><h2 id="sign-in-and-verify-identity" tabindex="-1">Iniciar y verificar la identidad <a class="header-anchor" href="#sign-in-and-verify-identity" aria-label="Permalink to &quot;Iniciar y verificar la identidad {#sign-in-and-verify-identity}&quot;">​</a></h2><ol><li>Abre <strong>Settings → Account</strong>. Lee el estado actual antes de iniciar otro acceso.</li><li>Pulsa <strong>Sign in</strong>. El escritorio inicia un receptor de retorno local y abre la página de acceso configurada en el navegador del sistema.</li><li>Completa el acceso del servicio y vuelve a TikTools. Si no se abrió el navegador, utiliza la URL mostrada para ese intento. Trátala como privada y no la publiques.</li><li>Espera a que el estado indique sesión iniciada. Confirma nombre o correo antes de abrir un catálogo privado o equipo.</li><li>Despliega los diagnósticos de Account si aparece un error. Usa <strong>Cancel</strong> para abandonar un intento pendiente en lugar de mantener varios activos.</li><li>Al terminar en un equipo compartido, pulsa <strong>Sign out</strong> y verifica el cambio de estado.</li></ol><p>El host nativo administra el token de sesión. Guarda las credenciales mediante el almacén del sistema operativo y solo entrega estado no secreto a la interfaz. No existe una alternativa de archivo en texto plano si falla el almacenamiento seguro. Copiar la carpeta de datos no transporta una sesión autenticada.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado y estado {#expected-result-and-status}&quot;">​</a></h2><p>El acceso nativo, la restauración y el cierre de sesión están disponibles en hosts compilados con autenticación Cloud. Una cuenta configurada puede restaurarse al reiniciar y validarse de nuevo con el servicio. Introducir otra cookie de TikTok no repara un host sin Cloud o sin configuración.</p><p>La disponibilidad del acceso y la aceptación real de proveedores y plataformas dependen del servicio desplegado y del equipo. Una validación local no demuestra que funcionen todas las rutas de producción.</p><h2 id="recovery" tabindex="-1">Recuperación <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperación {#recovery}&quot;">​</a></h2><p>Si el intento caducó o se canceló, ciérralo e inicia uno nuevo. Ante fallos de red o servicio, conserva el código de diagnóstico y repite tras recuperarse. Si falla el almacén de credenciales, restablece el almacenamiento seguro del sistema; no pegues tokens en ajustes ni en mensajes de soporte. Consulta <a href="./changes.html">Changes</a> para sincronización explícita y <a href="./collaboration.html">colaboración</a> para los permisos separados.</p><h2 id="operational-details" tabindex="-1">Detalles de operación <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalles de operación {#operational-details}&quot;">​</a></h2><p>Cerrar sesión elimina credenciales locales y limpia el contexto antes de intentar revocación remota de mejor esfuerzo. La UI sin sesión confirma retirada local, no revocación remota durante fallo de red. Usa administración de sesiones del servicio si existe. Exporta Diagnostics antes de cerrar/cambiar cuenta conocida: se limpia ese historial UI. Cookies TikTok y sesiones de host remoto son identidades separadas.</p>',13)])])}const v=a(s,[["render",r]]);export{m as __pageData,v as default};
